// keys: "12x23"
// expect: exit 12
// screen: 0 1 ADD 2   2 ADD 5   3 QUIT
// screen: 1 ?
// screen: 2 total 12
int main(void)
{
    int total = 0, k;
    cls();
    puts("1 ADD 2   2 ADD 5   3 QUIT");
    while ((k = getkey()) != '3') {
        switch (k) {
        case '1':
            total += 2;
            break;
        case '2':
            total += 5;
            break;
        default:
            puts("?");
        }
    }
    printf("total %d\n", total);
    return total;
}
